pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 amount, uint256 dummy) public {
        amount = bound(amount, 0, 1 ether);

        Reverter rev = new Reverter();

        vm.deal(address(c), 1 ether);

        bool ok;
        try c.sendMoney(address(rev), amount, abi.encode(dummy)) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok == false);
    }
}

contract Reverter {
    fallback() external payable {
        revert("revert in helper");
    }
}
